class Solution {
public:
    int numberCount(int a, int b) {
        int ans = 0;
        for (int x = a; x <= b; ++x) {
            int y = x, mask = 0;
            bool ok = true;
            do {
                int d = y % 10;
                if (mask & (1 << d)) { ok = false; break; }
                mask |= 1 << d;
                y /= 10;
            } while (y);
            ans += ok;
        }
        return ans;
    }
};
